function urlBase64ToBytes(value){const pad='='.repeat((4-(value.length%4))%4),raw=atob((value+pad).replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)))}
async function pushSupported(){return Boolean(window.PushManager&&navigator.serviceWorker&&window.isSecureContext)}
async function currentPush(){if(!await pushSupported())return null;const reg=await navigator.serviceWorker.getRegistration('/');return reg&&reg.pushManager.getSubscription()}
