async function refreshPushButton(){const btn=qs('#pushAlertsBtn'),status=qs('#deviceAlertStatus');if(!btn)return;const alert=await deviceAlertState();status.textContent=alert.message;if(alert.state==='Unsupported'){btn.hidden=true;return}btn.hidden=false;btn.disabled=alert.state==='Blocked';btn.textContent=alert.state==='On'?'Disable expiry alerts':alert.state==='Blocked'?'Expiry alerts blocked':'Enable expiry alerts'}
