function applyBatchChanges(changes){let touched=false,updated=false,removed=false;for(const c of changes){const i=medicines.findIndex(m=>m.id===c.id);if(c.kind==='remove'){if(i>=0){medicines.splice(i,1);touched=true;if(openBatchState(c.id))removed=true}continue}if(i<0){medicines.push(c.batch);touched=true}else if(medicines[i].revision<c.batch.revision){medicines[i]=c.batch;touched=true;if(openBatchState(c.id))updated=true}}if(!touched)return;sortMedicines();dashboard();inventory();toast(options.term(removed?'A medicine you have open was removed elsewhere.':updated?'A medicine you have open was updated elsewhere. Reopen it to see the latest version.':'Inventory updated.'))}
