function showInviteGate(title,description){qs('#appShell').hidden=true;qs('#inviteGate').hidden=false;qs('#shopSetupForm').hidden=true;qs('#inviteGateChoices').replaceChildren();qs('#inviteGateTitle').textContent=title;qs('#inviteGateDescription').textContent=description;qs('#inviteGateTitle').focus();}
function showSetupGate(){showInviteGate('Set up your Shop','Choose the Shop name and the display name you want to use. Setup is completed only when you select Set up Shop.');const form=qs('#shopSetupForm');form.hidden=false;form.elements.shopName.focus()}
function renderInvitations(invitations){const choices=qs('#inviteGateChoices');choices.replaceChildren(...invitations.map(invitation=>{const expiry=invitationExpiry(invitation.expires_at);const button=el('button',{class:'button primary',type:'button',text:'Accept invitation'});button.addEventListener('click',async()=>{button.disabled=true;button.textContent='Accepting…';gateStatus('Adding you to this Shop…');try{await api(`/api/household/invitations/${encodeURIComponent(invitation.id)}/accept`,{method:'POST',body:'{}'});gateStatus('Invitation accepted. Opening your Shop…');location.reload()}catch(error){button.disabled=false;button.textContent='Accept invitation';gateStatus(error.status===409?'This account already belongs to another Shop.':error.status===429?'Too many attempts. Please wait and try again.':error.message,true)}});return el('article',{class:'invite-choice'},el('strong',{text:invitation.household_name}),el('span',{text:invitation.role==='owner'?'Owner access':'Member access'}),el('time',{datetime:invitation.expires_at,text:`Expires ${expiry}`}),button)}));}
async function start(){const retry=qs('#inviteGateRetry');retry.hidden=true;try{const status=await api('/api/shop/onboarding-status');if(status.membership){await openConfirmedShop();return}if(status.setupEligible){showSetupGate();return}const pending=decodePendingPage(await api('/api/household/invitations/pending'));if(pending.invitations?.length){showInviteGate('You’re invited to a Shop','This signed-in account has an invitation waiting.');renderInvitations(pending.invitations);return}showInviteGate('No Shop invitation found','This signed-in account is not yet part of a Shop. Ask a Shop owner to send an invitation, then try again.')}catch(error){if(await offlineBoot(error))return;if(error.status===404){localShopMode=true;showApp();return}showInviteGate(error.status===401?'Sign-in required':'We could not check your Shop access',error.status===401?'Sign in through Cloudflare Access, then refresh this page.':error.status===429?'Too many requests. Please wait a moment before trying again.':error.message||'Please try again.');gateStatus(error.message||'Shop access check failed.',true);retry.hidden=false;retry.focus()}}
qs('#shopSetupForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget;if(!form.checkValidity()){form.reportValidity();return}const button=qs('button[type=submit]',form);button.disabled=true;form.setAttribute('aria-busy','true');gateStatus('Setting up your Shop…');try{await api('/api/shop/onboarding',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});gateStatus('Shop setup complete. Opening inventory…');location.reload()}catch(error){gateStatus(error.message,true);button.disabled=false}finally{form.removeAttribute('aria-busy')}});
if('serviceWorker' in navigator&&window.isSecureContext)navigator.serviceWorker.register('/sw.js',{scope:'/'}).catch(()=>{});
qs('#inviteGateRetry').addEventListener('click',start);start();
